-- EDITED BY HAND. drizzle-kit re-emitted four statements here that migration
-- 0004 has already applied:
--
--   ALTER TABLE accounts ADD COLUMN unit ... GENERATED ALWAYS AS ... STORED
--   ALTER TABLE entries  ADD COLUMN unit text NOT NULL
--   ALTER TABLE entries  ADD CONSTRAINT entries_account_unit_fk ...
--   ALTER TABLE accounts ADD CONSTRAINT accounts_id_unit_key UNIQUE (id, unit)
--
-- They were removed. Running them would have failed with 42701
-- (duplicate_column) and taken the whole migration with it.
--
-- This is the hand-written-migration drift that CONVENTIONS.md warns about,
-- showing up in practice. drizzle-kit diffs against its own snapshot in
-- meta/, and 0004 was written by hand so the snapshot never learned about it.
-- The next `generate` therefore believed those columns were missing and
-- proposed creating them.
--
-- It is self-correcting from here: meta/0005_snapshot.json, written by this
-- same generate, *does* contain the unit columns, so future diffs start from
-- the right place. The lesson is that every `generate` following a hand-written
-- migration must have its SQL read before it is run — which is why the workflow
-- is generate, review the diff, then migrate, and never `push`.
ALTER TABLE "orders" ADD CONSTRAINT "orders_cash_account_id_accounts_id_fk" FOREIGN KEY ("cash_account_id") REFERENCES "public"."accounts"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "orders" ADD CONSTRAINT "orders_asset_account_id_accounts_id_fk" FOREIGN KEY ("asset_account_id") REFERENCES "public"."accounts"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "orders" ADD CONSTRAINT "orders_symbol_instruments_symbol_fk" FOREIGN KEY ("symbol") REFERENCES "public"."instruments"("symbol") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "orders" ADD CONSTRAINT "orders_transaction_id_ledger_transactions_id_fk" FOREIGN KEY ("transaction_id") REFERENCES "public"."ledger_transactions"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "orders_external_id_key" ON "orders" USING btree ("external_id");--> statement-breakpoint
CREATE INDEX "orders_cash_account_idx" ON "orders" USING btree ("cash_account_id","created_at");--> statement-breakpoint

